type NotFound struct{ ID int }

func (e *NotFound) Error() string { return fmt.Sprintf("товар %d не найден", e.ID) }

func find(id int) error {
    var err *NotFound
    if id < 0 {
        err = &NotFound{ID: id}
    }
    return err
}

func main() {
    if err := find(5); err != nil {
        fmt.Println("ошибка!")   // <- выполнится
    }
}

